<div class="page-title">Notifications</div><p class="page-subtitle">Trade and Pre/Post Review reminders and workflow alerts.</p>
<div class="card"><div class="actions"><?php foreach(['all'=>'All','trade'=>'Trade','day'=>'Day','week'=>'Week','month'=>'Month','year'=>'Year'] as $key=>$label):?><a class="secondary-link <?=$filter===$key?'active-filter':''?>" href="/notifications?filter=<?=$key?>"><?=e($label)?></a><?php endforeach;?></div></div>
<div class="card table-wrap"><table><thead><tr><th>Date</th><th>Type</th><th>Title</th><th>Message</th><th></th></tr></thead><tbody><?php foreach($notifications as $n):?><tr><td><?=e($n['created_at'])?></td><td><?=e($n['type'])?></td><td><strong><?=e($n['title'])?></strong></td><td><?=e($n['message'])?></td><td><?php if(!$n['is_read']):?><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($n['id'])?>"><input type="hidden" name="filter" value="<?=e($filter)?>"><button class="secondary">Mark read</button></form><?php else:?>Read<?php endif;?></td></tr><?php endforeach;if(!$notifications):?><tr><td colspan="5" class="muted">No notifications.</td></tr><?php endif;?></tbody></table></div>
<style>.active-filter{background:#111827!important;color:#fff!important}</style>
